import {sampleScene,sceneClock} from './timeline.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const clockLabel=seconds=>`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;
function titleForKind(kind){return {opening:'라인 배치',gank:'갱킹',dive:'다이브',skirmish:'소규모 교전',dragon:'드래곤',herald:'협곡의 전령','baron-setup':'바론 시야',baron:'바론',siege:'공성',teamfight:'한타',flank:'측면 진입',recall:'귀환 · 정비',nexus:'넥서스'}[kind]??'교전';}
export function sceneNarration(scene,progress){
 if(progress>=.8)return scene.text;
 if(scene.kind==='opening')return '탑·미드·바텀과 정글 입구로 챔피언들이 이동합니다.';
 if(scene.kind==='recall')return '챔피언들이 귀환하며 체력을 회복하고 다음 동선을 준비합니다.';
 if(scene.kind==='gank'||scene.kind==='dive')return `${scene.location==='top'?'탑':scene.location==='bot'?'바텀':'미드'} 측면으로 정글러가 접근합니다. 라이너가 퇴로를 좁히며 호응합니다.`;
 if(scene.kind==='baron-setup')return '정글·서포터가 바론 강가에 먼저 진입합니다. 딜러는 라인을 정리하며 합류를 준비합니다.';
 if(['baron','dragon','herald'].includes(scene.kind))return `${titleForKind(scene.kind)} 둥지로 양 팀이 모입니다. 전방이 진입하고 딜러는 사거리를 유지합니다.`;
 if(scene.kind==='siege')return '전방이 포탑 앞으로 이동하고 원거리 딜러가 뒤에서 공성을 시작합니다.';
 if(scene.kind==='flank')return '측면으로 우회하는 챔피언이 있습니다. 앞뒤에서 진입하며 상대 딜러의 퇴로를 노립니다.';
 if(scene.kind==='nexus')return '승기를 잡은 팀이 적진으로 진입합니다. 남은 챔피언이 넥서스를 지키려 합니다.';
 return '전방 챔피언이 먼저 진입합니다. 딜러와 서포터가 후방에서 교전에 합류합니다.';
}
function killsUntil(timeline,index,progress){return timeline.slice(0,index).flatMap(s=>s.kills).concat(timeline[index].kills.slice(0,Math.max(0,Math.floor((progress-.48)/.3*timeline[index].kills.length)+1)));}
export function riftSvg(c,set,scene){
 const {E,state:s}=c;
 const towers=[...[[80,390],[80,270],[80,130],[140,80],[290,80],[440,80],[150,450],[225,375],[280,320]].map(p=>[...p,'blue']),...[[520,210],[520,335],[520,470],[455,520],[305,520],[160,520],[450,150],[375,225],[320,280]].map(p=>[...p,'red'])];
 return `<svg viewBox="0 0 600 600" class="rift-svg" role="img" aria-label="상황에 따라 챔피언 초상화가 이동하는 소환사의 협곡"><defs><linearGradient id="rift-ground" x2="1" y2="1"><stop stop-color="#17332d"/><stop offset="1" stop-color="#122520"/></linearGradient><pattern id="rift-grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0v30" stroke="#52755b" stroke-opacity=".07" fill="none"/></pattern><filter id="rift-glow"><feGaussianBlur stdDeviation="4"/></filter>${scene.actors.map((a,i)=>`<clipPath id="champ-clip-${i}"><circle r="17"/></clipPath>`).join('')}</defs><rect x="6" y="6" width="588" height="588" rx="14" fill="url(#rift-ground)" stroke="#486057" stroke-width="3"/><rect width="600" height="600" fill="url(#rift-grid)"/><g fill="#214939" stroke="#2d5d44" stroke-width="2"><path d="M112 145q62-55 105 22l-30 72-72-32zM130 302l61-57 63 49-52 80-69-13zM231 416l52-64 55 43-32 74zM363 126l73 14 25 72-65 28-35-58zM365 279l83-30 35 62-30 58-62-33zM347 446l77-62 52 58-40 38z"/></g><path d="M70 535V70H535V535ZM70 535 535 70" stroke="#857e59" stroke-opacity=".68" stroke-width="23" fill="none" stroke-linejoin="round"/><path d="M70 535V70H535V535ZM70 535 535 70" stroke="#b2a474" stroke-opacity=".2" stroke-width="5" fill="none"/><path d="M87 90Q235 274 300 300T510 510" stroke="#286575" stroke-width="43" fill="none" opacity=".8"/><path d="M87 90Q235 274 300 300T510 510" stroke="#6eacaa" stroke-width="3" fill="none" opacity=".35"/><g fill="none" stroke="#65836c" stroke-width="7" stroke-opacity=".28"><path d="M70 450q116 20 133-104t50-157M146 534q80-95 182-105M533 150q-110 10-125 104t-44 160M448 70q-80 85-170 90"/></g><g class="rift-brush" fill="#315a38"><path d="m104 192 42-18-9 34-31 10zm144 78 41-15-15 34-28 6zm117 54 39-10-11 31-25 5zm89 61 32-9-5 31-31 5z"/></g><g class="rift-towers">${towers.map(([x,y,side],i)=>`<g class="rift-tower ${side}" data-tower="${i}" transform="translate(${x},${y})"><circle r="11"/><path d="M-6 5v-10h3v-5h6v5h3V5z"/><circle class="tower-range" r="35"/></g>`).join('')}</g><g class="rift-nexus blue" transform="translate(63 537)"><circle r="32"/><path d="m0-22 16 22L0 22-16 0z"/></g><g class="rift-nexus red" transform="translate(537 63)"><circle r="32"/><path d="m0-22 16 22L0 22-16 0z"/></g><g class="rift-objective baron" transform="translate(205 195)"><ellipse rx="30" ry="24"/><path d="m-13 3 7-14 6 8 7-8 8 14-8 10H-7z"/><text y="42" text-anchor="middle">${scene.second<1200?'HERALD':'BARON'}</text></g><g class="rift-objective dragon" transform="translate(410 400)"><ellipse rx="30" ry="24"/><path d="m-14 7 8-14 7 3 13-9-5 18-9 8z"/><text y="42" text-anchor="middle">DRAGON</text></g><g class="scene-focus" transform="translate(${scene.focus.x} ${scene.focus.y})"><circle class="focus-glow" r="${scene.focus.radius}"/><circle r="${scene.focus.radius*.7}"/><text y="${-scene.focus.radius-10}" text-anchor="middle">${esc(scene.title)}</text></g><g class="movement-paths">${scene.actors.map(a=>`<path class="${a.side}" d="${a.path.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ')}"/>`).join('')}</g><g class="combat-effects">${scene.kills.map((k,i)=>`<g data-kill-effect="${i}" opacity="0"><line class="skill-projectile" x1="0" y1="0" x2="0" y2="0"/><circle class="skill-impact" r="22"/><text class="damage-number" text-anchor="middle">${200+(i*137)%600}</text></g>`).join('')}</g><g class="champion-units">${scene.actors.map((a,i)=>{const player=s.players[a.id];return `<g class="champion-token ${a.side}" data-player="${esc(a.id)}" data-champion="${a.champion}" transform="translate(${a.from[0]} ${a.from[1]})"><title>${esc(player?.name??a.role)} · ${esc(E.database().champMap[a.champion]?.name)} · ${a.role}</title><circle class="token-recall" r="26"/><circle class="token-ring" r="20"/><image href="./assets/champions/${a.champion}.png" x="-17" y="-17" width="34" height="34" clip-path="url(#champ-clip-${i})"/><rect class="token-health-bg" x="-21" y="-30" width="42" height="5" rx="1"/><rect data-token-hp x="-21" y="-30" width="42" height="5" rx="1"/><text class="token-role" text-anchor="middle" y="34">${esc(player?.name??a.role)}</text><g class="token-death" opacity="0"><path d="m-10-10 20 20m0-20-20 20"/><text y="6" text-anchor="middle">30</text></g></g>`;}).join('')}</g><g class="rift-victory" opacity="0"><rect x="150" y="225" width="300" height="130" rx="5"/><text x="300" y="278" text-anchor="middle">VICTORY</text><text x="300" y="320" text-anchor="middle">${esc(c.teamName(set.winner))}</text></g></svg>`;
}
function sidePlayers(c,set,side){const {E,state:s,img,esc}=c,id=set[side];return `<aside class="spectator-team ${side}"><h2>${esc(c.teamName(id))}</h2>${E.ROLES.map(role=>{const p=set.stats.find(p=>p.team===id&&p.role===role);return `<div class="spectator-player" data-live-player="${esc(p.player)}">${img(p.champion)}<div><strong>${esc(s.players[p.player]?.name??role)}</strong><small>${role} · ${esc(E.database().champMap[p.champion].name)}</small><div class="live-health"><i style="width:100%"></i></div><span class="live-kda">0 / 0 / 0</span></div></div>`;}).join('')}<div class="side-objectives"><span>드래곤 <b data-dragons="${esc(id)}">0</b></span><span>킬 <b data-kills="${esc(id)}">0</b></span></div></aside>`;}
export function viewerMarkup(c){
 const {state:s,ui,btn,badge,esc}=c,{m,set}=c.viewerData();if(!set)return '<div class="empty">기록을 찾을 수 없습니다.</div>';
 const timeline=c.timelineForSet(set),index=Math.min(ui.viewerIndex,timeline.length-1),scene=timeline[index],finished=index===timeline.length-1&&(ui.sceneProgress??0)>=1;
 const score={[set.blue]:0,[set.red]:0};for(const z of m.sets.slice(0,s.viewing.setIndex+(finished?1:0)))score[z.winner]++;
 return `<section class="live-spectator"><header class="live-spectator-header"><h1>경기 관전 · ${set.number}세트</h1><span>${esc(m.competition)} · PATCH ${c.E.patchLabel(set.patch)}</span>${badge(finished?'FINAL':'LIVE',finished?'gold':'red')}<span class="live-reconstruction">게임 내 주요 장면 재구성</span>${btn('집무실','nav','data-id="home"','compact ghost')}</header><div class="live-scoreboard"><div class="blue"><strong>${esc(c.teamName(set.blue))}</strong><b data-team-score="${esc(set.blue)}">0</b><span data-team-gold="${esc(set.blue)}">2.5K</span></div><div class="live-series"><strong>${score[set.blue]} <i>:</i> ${score[set.red]}</strong><time id="live-clock">${clockLabel(scene.second)}</time><small>GAME ${set.number} · BO${m.bestOf}</small></div><div class="red"><span data-team-gold="${esc(set.red)}">2.5K</span><b data-team-score="${esc(set.red)}">0</b><strong>${esc(c.teamName(set.red))}</strong></div></div><div class="live-advantage" aria-live="polite"><strong id="live-gold-lead">골드 동률</strong><span id="live-swing">교전과 오브젝트에 따라 우위가 바뀝니다.</span><small id="live-battle-context" hidden></small></div><div class="spectator-layout">${sidePlayers(c,set,'blue')}<div class="rift-center"><div class="live-rift" data-scene-kind="${scene.kind}">${riftSvg(c,set,scene)}<div class="rift-scene-tag">${esc(titleForKind(scene.kind))}</div><div class="rift-killfeed" aria-live="polite"></div></div><div class="scene-narration"><span>${esc(scene.title)}</span><p id="scene-narration">${esc(sceneNarration(scene,ui.sceneProgress??0))}</p></div></div>${sidePlayers(c,set,'red')}</div><div class="live-playback"><div class="toolbar">${btn(ui.viewerPlaying?'일시 정지':'재생','viewer-play','','compact')}${[1,2,4,8].map(n=>btn(`x${n}`,'viewer-speed',`data-speed="${n}"`,ui.viewerSpeed===n?'compact primary':'compact')).join('')}${btn('다음 장면','viewer-next','','compact')}${btn('세트 결과 보기','viewer-end','','compact ghost')}</div>${finished?btn(ui.replay?'기록실로':m.status==='done'?'시리즈 마치기':'다음 세트 준비','viewer-continue','','primary'):''}</div><div class="scene-timeline" aria-label="경기 장면 타임라인">${timeline.map((z,i)=>`<button class="${i===index?'active':''} ${i<index?'seen':''}" data-action="viewer-scene" data-index="${i}" ${!ui.replay&&i>index+1?'disabled':''}><small>${clockLabel(z.second)}</small><span>${esc(i<=index?z.title:titleForKind(z.kind))}</span></button>`).join('')}</div>${finished?`<section class="panel flush live-results"><div class="panel-head spread"><h2>세트 기록</h2><div class="toolbar">${m.sets.map((z,i)=>btn(`${i+1}세트`,'viewer-set',`data-index="${i}"`,'compact')).join('')}</div></div><div class="table-wrap"><table><thead><tr><th>구단</th><th>선수</th><th>챔피언</th><th>K / D / A</th><th>CS</th><th>피해량</th></tr></thead><tbody>${set.stats.map(p=>`<tr class="${p.team===s.myTeam?'mine':''}"><td>${esc(c.teamName(p.team))}</td><td>${p.role} · ${esc(s.players[p.player]?.name??p.role)}</td><td><span class="player-label">${c.img(p.champion)} ${esc(c.E.database().champMap[p.champion].name)}</span></td><td>${p.k} / ${p.d} / ${p.a}</td><td>${p.cs}</td><td>${(p.damage/1000).toFixed(1)}K</td></tr>`).join('')}</tbody></table></div></section>`:''}</section>`;
}
export function paintScene(c){
 const {set}=c.viewerData();if(!set)return;const timeline=c.timelineForSet(set),index=Math.min(c.ui.viewerIndex,timeline.length-1),scene=timeline[index],progress=c.ui.sceneProgress??0;
 const actors=sampleScene(scene,progress),map=Object.fromEntries(actors.map(a=>[a.id,a]));
 const dom=document.querySelector('.live-rift');if(!dom)return;
 for(const a of actors){const el=[...dom.querySelectorAll('[data-player]')].find(el=>el.dataset.player===a.id);if(!el)continue;el.setAttribute('transform',`translate(${a.x.toFixed(2)} ${a.y.toFixed(2)})`);el.classList.toggle('dead',a.visibleDeath);el.classList.toggle('recalling',a.recalling);el.querySelector('[data-token-hp]').setAttribute('width',Math.max(0,a.hp)*.42);el.querySelector('.token-death').setAttribute('opacity',a.visibleDeath?'1':'0');const small=document.querySelector(`[data-live-player="${CSS.escape(a.id)}"]`);if(small){small.classList.toggle('dead',a.visibleDeath);small.querySelector('.live-health i').style.width=a.hp+'%';}}
 for(let i=0;i<scene.kills.length;i++){const k=scene.kills[i],a=map[k.killer],v=map[k.victim],effect=dom.querySelector(`[data-kill-effect="${i}"]`);if(!effect||!a||!v)continue;const at=.48+i*.03,visible=progress>=at&&progress<Math.min(.95,at+.22);effect.setAttribute('opacity',visible?'1':'0');const line=effect.querySelector('line');line.setAttribute('x1',a.x);line.setAttribute('y1',a.y);line.setAttribute('x2',v.x);line.setAttribute('y2',v.y);const circle=effect.querySelector('circle');circle.setAttribute('cx',v.x);circle.setAttribute('cy',v.y);const text=effect.querySelector('text');text.setAttribute('x',v.x);text.setAttribute('y',v.y-38-(progress-at)*40);}
 const kills=killsUntil(timeline,index,progress);const prior=index?timeline[index-1]:null;const lead=(prior?.lead??0)+((scene.lead??0)-(prior?.lead??0))*progress;
 for(const id of [set.blue,set.red]){const n=kills.filter(k=>k.team===id).length;document.querySelectorAll(`[data-team-score="${CSS.escape(id)}"],[data-kills="${CSS.escape(id)}"]`).forEach(el=>el.textContent=n);const actualGold=scene.gold?.[id],beforeGold=prior?.gold?.[id]??2500;
  const gold=Number.isFinite(actualGold)?beforeGold+(actualGold-beforeGold)*progress:2500+sceneClock(scene,progress)/60*1500+(id===set.blue?lead:-lead)/2;
  const el=document.querySelector(`[data-team-gold="${CSS.escape(id)}"]`);if(el)el.textContent=(Math.max(2500,gold)/1000).toFixed(1)+'K' ;const drakes=progress>=.8?scene.dragons[id]:prior?.dragons[id]??0;document.querySelectorAll(`[data-dragons="${CSS.escape(id)}"]`).forEach(el=>el.textContent=drakes);}
 const advantage=document.querySelector('#live-gold-lead'),swing=document.querySelector('#live-swing');
 if(advantage){const ahead=lead>=0?set.blue:set.red;advantage.textContent=Math.abs(lead)<100?'골드 동률':`${c.state.teams[ahead]?.abbr??ahead} +${(Math.abs(lead)/1000).toFixed(1)}K 골드`;advantage.dataset.side=Math.abs(lead)<100?'even':lead>0?'blue':'red';}
 if(swing){const resolved=progress>=.8;swing.textContent=resolved&&scene.kind==='nexus'?set.comeback?.winnerMaxDeficit>=3000?`최대 ${(set.comeback.winnerMaxDeficit/1000).toFixed(1)}K 열세를 극복한 승리`:'넥서스 파괴로 경기 종료':resolved&&scene.comeback?'골드 역전!':resolved&&scene.objective?.steal?'바론 스틸!':resolved&&scene.bounty?`제압·오브젝트 보상 +${(scene.bounty/1000).toFixed(1)}K`:Number.isFinite(scene.blueWinProbability)?`이번 교전 예상 · BLUE ${Math.round(scene.blueWinProbability*100)}% / RED ${Math.round((1-scene.blueWinProbability)*100)}%`:'다음 교전과 오브젝트를 준비합니다.';}
 const battleContext=document.querySelector('#live-battle-context');
 if(battleContext){
  battleContext.hidden=!Number.isFinite(scene.goldWeight);const comp=scene.compositionGap??0;
  const label=Math.abs(comp)<.25?'조합 상성 대등':`${c.state.teams[comp>0?set.blue:set.red]?.abbr??''} 조합 우세`;
  const context=scene.kind==='siege'?'공성전':scene.kind==='baron-setup'?'바론 시야 싸움':scene.roles?`${scene.roles.includes('TOP')?'상체':'하체'} ${scene.roles.length}:${scene.roles.length}`:'5:5 한타';
  const phase=Number.isFinite(scene.championPhaseGap)?` · ${c.E.fightStage(scene.minute)} ${context} · 성장·교전 특성 반영`:'';
  let personal='';
  if(scene.championFormImpact){const [side,id,k,d,a]=scene.championFormImpact,p=c.E.championCombat(id,scene.minute,scene.kind,{k,d,a});personal=` · ${c.state.teams[set[side]]?.abbr??side} ${c.E.database().champMap[id]?.name??id} 교전 직전 ${k}/${d}/${a}: ${p.label}`;}
  battleContext.textContent=`${scene.goldWeight<1?`장기전 · 골드 영향 ${Math.round(scene.goldWeight*100)}%`:'골드 차이 기본 반영'} · ${label}${phase}${personal}`;
 }

 for(const p of set.stats){const el=document.querySelector(`[data-live-player="${CSS.escape(p.player)}"] .live-kda`);if(el)el.textContent=`${kills.filter(k=>k.killer===p.player).length} / ${kills.filter(k=>k.victim===p.player).length} / ${kills.filter(k=>k.assists.includes(p.player)).length}`;}
 const feed=dom.querySelector('.rift-killfeed');const key=kills.length+'|'+index;if(feed.dataset.key!==key){feed.dataset.key=key;feed.innerHTML=kills.slice(-4).reverse().map(k=>`<div class="kill-entry ${k.team===set.blue?'blue':'red'}"><img src="./assets/champions/${k.killerChampion}.png" alt=""> <strong>${esc(c.state.players[k.killer]?.name??'')}</strong><span>처치</span><img src="./assets/champions/${k.victimChampion}.png" alt=""><strong>${esc(c.state.players[k.victim]?.name??'')}</strong></div>`).join('');}
 const narration=document.querySelector('#scene-narration'),text=sceneNarration(scene,progress);if(narration&&narration.textContent!==text)narration.textContent=text;
 const clock=document.querySelector('#live-clock');if(clock)clock.textContent=clockLabel(sceneClock(scene,progress));
 const victory=dom.querySelector('.rift-victory');victory?.setAttribute('opacity',scene.kind==='nexus'&&progress>.75?'1':'0');
 const objective=dom.querySelector('.rift-objective.'+scene.objective?.kind);if(objective)objective.classList.toggle('captured',progress>=.8);
}
